#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

banner "Deploy apps/backend to Render + apps/web to Cloudflare Pages"

say "Per ADR 0016: Render (backend + Postgres) and Cloudflare Pages (frontend)."
say "This writes real production values to $ENV_FILE as YOUR OWN local record -"
say "apps/backend/apps/web never read that file themselves; the dashboards you"
say "paste into are the actual source of truth. Since it holds a real secret and"
say "a real DB connection string, delete it once you've confirmed everything's"
say "live, or keep it somewhere private - it's git-ignored, never commit it."
say "There is no CI configured yet, so nothing here touches GitHub secrets."

# ── Stage 1: Render Postgres ────────────────────────────────────────────────
stage "Render: create the Postgres database"
say "A real, paid instance - never Render's free Postgres tier, which"
say "auto-deletes 30 days after creation (a trap, not a bundled free DB; see"
say "ADR 0016)."
open_url "https://dashboard.render.com/new/database"
step "Sign in / create a Render account if you don't have one yet."
step "Name: something like 'towing-backend-db'."
step "Plan: 'Basic-256mb' (~\$6/month) - NOT the Free plan."
step "Region: pick one - you'll use the same region for the web service below."
step "Click 'Create Database' and wait for it to finish provisioning."
step "On the database's page, copy the 'Internal Database URL' (not External -"
step "the web service will live in the same Render account/region, so Internal"
step "is the right, lower-latency choice)."
ask RENDER_POSTGRES_URL_RAW "Paste the Internal Database URL:"
# apps/backend's async engine (towing_backend/db.py) passes the URL straight
# to create_async_engine with zero translation of its own - it needs the
# +asyncpg driver named explicitly, which Render's own URL never includes.
RENDER_POSTGRES_URL="${RENDER_POSTGRES_URL_RAW/postgresql:\/\//postgresql+asyncpg://}"
RENDER_POSTGRES_URL="${RENDER_POSTGRES_URL/postgres:\/\//postgresql+asyncpg://}"
write_env TOWING_BACKEND_DB_URL "$RENDER_POSTGRES_URL"
note "Translated to the driver form apps/backend actually needs:"
note "  $RENDER_POSTGRES_URL"

# ── Stage 2: Render web service ─────────────────────────────────────────────
stage "Render: create the backend web service"
warn "Root Directory MUST stay at the repo root - do NOT set it to apps/backend."
say "apps/backend depends on sibling workspace packages (packages/towing-core,"
say "packages/towing-app) that Render's monorepo directory-isolation would"
say "otherwise hide from the build entirely."
open_url "https://dashboard.render.com/new/web"
step "Connect your GitHub account if needed, then select this repo."
step "Name: something like 'towing-backend'."
step "Root Directory: leave BLANK (repo root)."
step "Runtime: Python 3."
step "Build Command: uv sync --frozen"
note "  (if the build fails with 'uv: command not found', edit this to:"
note "   pip install uv && uv sync --frozen - not verified ahead of time,"
note "   Render's default Python image may or may not ship uv already)"
step "Start Command: uv run --project apps/backend uvicorn towing_backend.asgi:app --host 0.0.0.0 --port \$PORT"
step "Plan: 'Starter' (~\$7/month) - NOT the Free plan, which sleeps after 15"
step "minutes idle (a real problem for a login-based app)."
note "Don't click Create yet - the next stage sets environment variables first,"
note "in the same form's Advanced section (or the Environment tab afterward)."
pause "Ready to continue to environment variables?"

# ── Stage 3: Render env vars + first deploy ─────────────────────────────────
stage "Render: environment variables and first deploy"
if command -v openssl >/dev/null 2>&1; then
  RENDER_SECRET=$(openssl rand -hex 32)
else
  RENDER_SECRET=$(python3 -c "import secrets; print(secrets.token_hex(32))")
fi
note "Generated a real secret for you (not something to copy from a website):"
printf '  %s\n' "$RENDER_SECRET"
step "Add environment variable: TOWING_BACKEND_SECRET = (the value printed above)"
step "Add environment variable: TOWING_BACKEND_DB_URL = $RENDER_POSTGRES_URL"
step "Add environment variable: TOWING_BACKEND_CORS_ORIGIN = http://localhost:5173"
note "  (placeholder for now - stage 6 updates this once the real Cloudflare"
note "   Pages URL exists, since it can't be known before that deploy happens)"
step "Click 'Create Web Service' (or 'Save Changes') and watch the Logs tab"
step "until the first deploy finishes."
warn "If it fails on 'uv: command not found', see stage 2's Build Command note."
step "Once live, copy the service URL from the top of its dashboard page"
step "(looks like https://towing-backend-xxxx.onrender.com)."
ask RENDER_BACKEND_URL "Paste the Render backend URL:"
write_env TOWING_BACKEND_SECRET "$RENDER_SECRET"
write_env RENDER_BACKEND_URL "$RENDER_BACKEND_URL"
step "Confirm it's alive: open ${RENDER_BACKEND_URL}/api/health in a browser -"
step "it should show {\"ok\":true}."
confirm "Did /api/health return {\"ok\":true}?" || warn "Fix the deploy (check Render's Logs tab) before continuing - re-run this wizard once it's healthy, it remembers what's already done."

# ── Stage 4: Cloudflare Pages project ───────────────────────────────────────
stage "Cloudflare: create the Pages project"
open_url "https://dash.cloudflare.com"
step "Sign in / create a Cloudflare account if needed."
step "Workers & Pages -> Create -> Pages -> Connect to Git -> select this repo."
step "Root directory: apps/web"
step "Framework preset: Vite, if offered (otherwise leave as None)."
step "Build command: npm run build"
step "Build output directory: dist"
note "Don't click Save and Deploy yet - the next stage sets VITE_API_BASE"
note "first, so it's baked into this very first build (Vite inlines env vars"
note "at build time, not at request time)."
pause "Ready to continue to environment variables?"

# ── Stage 5: Cloudflare env var + first deploy ──────────────────────────────
stage "Cloudflare: environment variable and first deploy"
step "Add environment variable (Production): VITE_API_BASE = $RENDER_BACKEND_URL"
note "  (Settings tab if the project already exists: Settings -> Environment"
note "   variables -> add for Production.)"
step "Click 'Save and Deploy' and wait for the build to finish."
step "Once live, copy the assigned URL (looks like https://towing-web-xxxx.pages.dev)."
ask CLOUDFLARE_PAGES_URL "Paste the Cloudflare Pages URL:"
write_env CLOUDFLARE_PAGES_URL "$CLOUDFLARE_PAGES_URL"

# ── Stage 6: cross-wire CORS back on Render ─────────────────────────────────
stage "Render: point CORS at the real frontend URL"
say "The backend needs to trust the frontend's real origin for the session"
say "cookie to actually flow (credentialed cross-origin requests can't use a"
say "wildcard - ADR 0016/#18)."
open_url "https://dashboard.render.com"
step "Open the towing-backend service -> Environment."
step "Update TOWING_BACKEND_CORS_ORIGIN to exactly: $CLOUDFLARE_PAGES_URL"
note "  (no trailing slash)"
step "Save - this triggers an automatic redeploy."
pause "Wait for the redeploy to finish (watch the Logs tab), then press Enter."

# ── Stage 7: smoke test ──────────────────────────────────────────────────────
stage "Smoke test the real deploy"
open_url "$CLOUDFLARE_PAGES_URL"
step "Confirm the free calculator loads and produces a result with no login"
step "(this is #38's fix - if it 404s, TOWING_BACKEND_CORS_ORIGIN or"
step "VITE_API_BASE is probably still wrong)."
step "Register a new test Account, log in, add a Truck Profile - confirm it"
step "saves and shows up in your Garage."
step "Log out, then confirm visiting a Garage page redirects you to login."
confirm "Did all three of those work?" || warn "Something's off - check Render's and Cloudflare's own logs before trusting this deploy."

finish
note "Remaining, not covered by this wizard: issue #37 (cookie_secure is still"
note "hardcoded False - flip it once it's implemented and redeploy), a custom"
note "domain before any Android client ships, and Resend (deferred - nothing"
note "reads RESEND_API_KEY yet, only needed once #32 ships)."
